import React, {useEffect, useMemo, useRef, useState} from "react";
import {
    Accordion,
    AccordionDetails,
    AccordionSummary,
    Alert,
    Chip,
    LinearProgress,
    TextField,
    Checkbox,
    FormControlLabel,
} from "@mui/material";
import {GridCellEditStopReasons, GridColDef, GridRowId, GridRowModel, GridToolbar, useGridApiRef} from "@mui/x-data-grid";
import ArrowBackOutlinedIcon from "@mui/icons-material/ArrowBackOutlined";
import AddOutlinedIcon from "@mui/icons-material/AddOutlined";
import ExpandMoreOutlinedIcon from "@mui/icons-material/ExpandMoreOutlined";
import styledCom from "styled-components";
import {useLocation, useNavigate} from "react-router-dom";
import {toast} from "react-toastify";
import {CategoryType} from "../../models/category";
import {ProductFileImportResult, ProductFileReviewLocationState} from "../../models/productFileImport";
import {getApiErrorMessage} from "../../api/errors";
import {getActiveFirmId} from "../../api/config";
import {useTranslation} from "../../i18n";
import {EmptyState, MainDiv, PageHeader, PageSubtitle, PageTitle, PageTitleGroup, StyledDataGrid, Surface} from "../../ui/commonStyled/commonStyled";
import CoreButton from "../../ui/buttons/coreButton";
import {useImportProductsFromFileMutation} from "../products/productsApi";
import {useGetLastLevelCategoriesQuery} from "../categories/categoriesApi";
import {stockApi} from "../stock/stockApi";
import {useAppDispatch} from "../../store/store";
import CatalogGenerationTabs from "./CatalogGenerationTabs";

type EditableProductRow = GridRowModel & {id: string; sourceRowNumber: number; gtin: string; name: string; count: number | string};
type CustomField = {id: string; name: string; defaultValue: string};

const Workspace = styledCom(Surface)({display: "grid", gap: 14});
const Steps = styledCom.div({display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginBottom: 16});
const Step = styledCom.div<{ $active?: boolean }>(({ $active }) => ({padding: "10px 12px", color: $active ? "var(--color-primary)" : "var(--color-muted)", fontSize: 13, fontWeight: 750, textAlign: "center", background: $active ? "var(--color-primary-soft)" : "var(--color-surface-soft)", border: `1px solid ${$active ? "var(--color-primary-border)" : "var(--color-border)"}`, borderRadius: 10}));
const TopBar = styledCom.div({display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12, flexWrap: "wrap"});
const Summary = styledCom.div({display: "flex", gap: 7, flexWrap: "wrap", marginTop: 6});
const BulkGrid = styledCom.div({display: "grid", gridTemplateColumns: "minmax(150px, 1fr) auto", gap: 8, alignItems: "center", "@media (max-width: 480px)": {gridTemplateColumns: "1fr"}});
const AddFieldGrid = styledCom.div({display: "grid", gridTemplateColumns: "minmax(180px, 1fr) minmax(180px, 1fr) auto", gap: 8, alignItems: "center", "@media (max-width: 760px)": {gridTemplateColumns: "1fr"}});
const FieldChips = styledCom.div({display: "flex", gap: 7, flexWrap: "wrap", marginTop: 10});
const Footer = styledCom.div({display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap", paddingTop: 4});

const documentFieldKey = (sourceKey: string) => `document_${sourceKey}`;
const customFieldKey = (id: string) => `additional_${id}`;
const toNonNegativeNumber = (value: unknown) => {
    if (value == null || (typeof value === "string" && !value.trim())) return null;
    const normalized = typeof value === "string"
        ? value.trim().replace(/\s+/g, "").replace(",", ".")
        : value;
    const parsed = typeof normalized === "number" ? normalized : Number(normalized);
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : null;
};
const parseEditableNumber = (value: unknown) => toNonNegativeNumber(value) ?? String(value ?? "");
const buildDefaultFields = (state: ProductFileReviewLocationState | null): CustomField[] => Object.entries(state?.defaultAdditionalFields ?? {}).map(([name, value], index) => ({id: `company_${index}`, name, defaultValue: value}));

const ProductFileReviewPage = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();
    const dispatch = useAppDispatch();
    const location = useLocation();
    const state = location.state as ProductFileReviewLocationState | null;
    const storageKey = `vivotech.product-file-review.${getActiveFirmId()}.${location.key}.${state?.file?.name}.${state?.file?.lastModified}.${state?.file?.size}`;
    const [savedReview] = useState<{draft: NonNullable<ProductFileReviewLocationState["reviewDraft"]>; result: ProductFileImportResult | null} | null>(() => {
        try {const saved = JSON.parse(sessionStorage.getItem(storageKey) || "null"); return Array.isArray(saved?.draft?.rows) && Array.isArray(saved?.draft?.customFields) && Array.isArray(saved?.draft?.excluded) ? saved : null;} catch {return null;}
    });
    const restoredDraft = savedReview?.draft ?? state?.reviewDraft;
    const [persistenceWarning, setPersistenceWarning] = useState(false);
    const apiRef = useGridApiRef();
    const editingCellRef = useRef<{id: GridRowId; field: string} | null>(null);
    const defaults = buildDefaultFields(state);
    const [customFields, setCustomFields] = useState<CustomField[]>(restoredDraft?.customFields ?? defaults);
    const [excluded, setExcluded] = useState<string[]>(restoredDraft?.excluded ?? []);
    const [updateStock, setUpdateStock] = useState(restoredDraft?.updateStock ?? false);
    const [rows, setRows] = useState<EditableProductRow[]>(() => (restoredDraft?.rows as EditableProductRow[] | undefined) ?? state?.preview.rows.map((row) => {
        const editable: EditableProductRow = {id: row.gtinNormalized, sourceRowNumber: row.sourceRowNumber, gtin: row.gtinNormalized, name: row.name, count: row.count ?? 0};
        state.preview.selectedColumns.forEach((column) => {editable[documentFieldKey(column.sourceKey)] = row.fieldValues[column.sourceKey] ?? "";});
        defaults.forEach((field) => {editable[customFieldKey(field.id)] = field.defaultValue;});
        return editable;
    }) ?? []);
    const rowsRef = useRef(rows);
    const [newFieldName, setNewFieldName] = useState("");
    const [newFieldDefault, setNewFieldDefault] = useState("");
    const [bulkCount, setBulkCount] = useState("");
    const [result, setResult] = useState<ProductFileImportResult | null>(state?.importResult ?? savedReview?.result ?? null);
    const [importProducts, productImport] = useImportProductsFromFileMutation();
    const {data: categories = []} = useGetLastLevelCategoriesQuery({type: CategoryType.Product});
    const categoryName = categories.find((category: any) => String(category.id) === state?.categoryId)?.name;
    useEffect(() => {
        if (!state?.file || !state.preview) return;
        try {
            sessionStorage.setItem(storageKey, JSON.stringify({result, draft: {rows, customFields, excluded, updatePrices: false, updateStock,
                mapping: JSON.stringify([state.categoryId, state.nameColumnKey, "", state.countColumnKey, state.selectedColumnKeys])}}));
            setPersistenceWarning(false);
        } catch {setPersistenceWarning(true);}
    }, [rows, customFields, excluded, updateStock, result, storageKey, state]);

    const columns = useMemo<GridColDef<EditableProductRow>[]>(() => {
        if (!state) return [];
        return [
            {field: "sourceRowNumber", headerName: t("Row"), width: 80, type: "number"},
            {field: "gtin", headerName: "GTIN", minWidth: 155, flex: 0.75},
            {field: "validation", headerName: "Проверка", minWidth: 240, flex: 1, valueGetter: ({row}) => excluded.includes(row.id) ? "Исключён из импорта" : result ? "Обработан" :
                !String(row.name ?? "").trim() ? "Укажите название" : !state.analysis?.isEpassDocument && toNonNegativeNumber(row.count) == null ? "Исправьте количество" : "Готов к сохранению"},
            {field: "name", headerName: t("Product name"), minWidth: 240, flex: 1.3, editable: result === null && !productImport.isLoading},
            ...(!state.analysis?.isEpassDocument ? [{field: "count", headerName: t("Stock quantity"), width: 135, editable: result === null && !productImport.isLoading, align: "right", headerAlign: "right", valueParser: parseEditableNumber} as GridColDef<EditableProductRow>] : []),
            ...state.preview.selectedColumns.map((column) => ({field: documentFieldKey(column.sourceKey), headerName: column.displayName, description: `Excel ${column.excelColumnName}`, minWidth: 170, flex: 1, editable: result === null && !productImport.isLoading} as GridColDef<EditableProductRow>)),
            ...customFields.map((field) => ({field: customFieldKey(field.id), headerName: field.name, minWidth: 170, flex: 1, editable: result === null && !productImport.isLoading} as GridColDef<EditableProductRow>)),
        ];
    }, [customFields, excluded, state, t, result, productImport.isLoading]);

    if (!state?.file || !state.preview) return <MainDiv><PageHeader><PageTitleGroup><PageTitle>{t("Product review")}</PageTitle><PageSubtitle>{t("Upload the file again to prepare products.")}</PageSubtitle></PageTitleGroup></PageHeader><CatalogGenerationTabs/><EmptyState><CoreButton muiType="success" text={t("Back to file upload")} onClick={() => navigate("/catalogGeneration/file", {replace: true})}/></EmptyState></MainDiv>;

    const backToSelection = () => result ? navigate("/catalogGeneration/file", {replace: true}) : navigate("/catalogGeneration/file", {replace: true, state: {...state, priceColumnKey: "", reviewDraft: {rows: flushActiveEdit(), customFields, excluded, updatePrices: false, updateStock,
        mapping: JSON.stringify([state.categoryId, state.nameColumnKey, "", state.countColumnKey, state.selectedColumnKeys])}}});
    const updateRows = (updater: (current: EditableProductRow[]) => EditableProductRow[]) => {
        const next = updater(rowsRef.current);
        rowsRef.current = next;
        setRows(next);
    };
    const updateRow = (nextRow: EditableProductRow) => {updateRows((current) => current.map((row) => row.id === nextRow.id ? nextRow : row)); return nextRow;};
    const applyBulkCount = () => {const value = toNonNegativeNumber(bulkCount); if (value == null) {toast.error(t("Enter a valid non-negative number.")); return;} updateRows((current) => current.map((row) => excluded.includes(row.id) ? row : ({...row, count: value})));};
    const addCustomField = () => {
        const name = newFieldName.trim();
        if (!name) {toast.error(t("Enter a field name.")); return;}
        if (name.length > 100 || newFieldDefault.length > 250) {toast.error(t("Field name or value is too long.")); return;}
        const names = [...state.preview.selectedColumns.map((column) => column.displayName), ...customFields.map((field) => field.name)];
        if (names.some((existing) => existing.localeCompare(name, undefined, {sensitivity: "accent"}) === 0)) {toast.error(t("Field names must be unique.")); return;}
        const field = {id: `${Date.now()}_${customFields.length}`, name, defaultValue: newFieldDefault};
        setCustomFields((current) => [...current, field]); updateRows((current) => current.map((row) => ({...row, [customFieldKey(field.id)]: field.defaultValue}))); setNewFieldName(""); setNewFieldDefault("");
    };
    const removeCustomField = (field: CustomField) => {setCustomFields((current) => current.filter((item) => item.id !== field.id)); updateRows((current) => current.map((row) => {const next = {...row}; delete next[customFieldKey(field.id)]; return next as EditableProductRow;}));};
    const flushActiveEdit = () => {
        let currentRows = rowsRef.current;
        const editingCell = editingCellRef.current;
        if (editingCell) {
            const editedRow = apiRef.current.getRowWithUpdatedValues(
                editingCell.id,
                editingCell.field,
            ) as EditableProductRow;
            currentRows = currentRows.map((row) => row.id === editedRow.id ? editedRow : row);
            rowsRef.current = currentRows;
            setRows(currentRows);
            apiRef.current.stopCellEditMode(editingCell);
            editingCellRef.current = null;
        }
        return currentRows;
    };
    const runImport = async () => {
        if (result || productImport.isLoading) return;
        const rowsForImport = flushActiveEdit();
        const includedRows = rowsForImport.filter(row => !excluded.includes(row.id));
        if (!includedRows.length) {toast.error("Выберите хотя бы один товар для сохранения."); return;}
        if (includedRows.some((row) => !String(row.name ?? "").trim() || String(row.name).length > 1000)) {toast.error("Укажите названия товаров до 1000 символов."); return;}
        if (!state.analysis?.isEpassDocument && includedRows.some((row) => toNonNegativeNumber(row.count) == null)) {toast.error("Количество должно быть неотрицательным числом."); return;}
        const valuesTooLong = includedRows.some((row) => [...state.preview.selectedColumns.map((column) => String(row[documentFieldKey(column.sourceKey)] ?? "")), ...customFields.map((field) => String(row[customFieldKey(field.id)] ?? ""))].some((value) => value.length > 250));
        if (valuesTooLong) {toast.error(t("Field value cannot exceed 250 characters.")); return;}
        const importRows = rowsForImport.map((row) => ({gtin: row.gtin, name: excluded.includes(row.id) ? "Исключён" : String(row.name).trim(), price: 0, count: state.analysis?.isEpassDocument ? 0 : toNonNegativeNumber(row.count) ?? 0, fieldValues: Object.fromEntries(state.preview.selectedColumns.map((column) => [column.sourceKey, excluded.includes(row.id) ? "" : String(row[documentFieldKey(column.sourceKey)] ?? "")])), additionalFields: Object.fromEntries(customFields.map((field) => [field.name, excluded.includes(row.id) ? "" : String(row[customFieldKey(field.id)] ?? "")]))}));
        const body = new FormData(); body.append("file", state.file); body.append("categoryId", state.categoryId); body.append("nameColumnKey", state.nameColumnKey); body.append("priceColumnKey", ""); body.append("countColumnKey", state.analysis?.isEpassDocument ? "" : state.countColumnKey); state.selectedColumnKeys.forEach((key) => body.append("selectedColumnKeys", key)); body.append("rowsJson", JSON.stringify(importRows));
        body.append("updateExistingPrices", "false"); body.append("updateExistingStock", String(!state.analysis?.isEpassDocument && updateStock)); excluded.forEach(gtin => body.append("excludedGtins", gtin));
        try {
            const response = await importProducts(body).unwrap();
            setResult(response);
            navigate(location.pathname + location.search, {replace: true, state: {...state, importResult: response,
                reviewDraft: {rows: rowsForImport, customFields, excluded, updatePrices: false, updateStock,
                    mapping: JSON.stringify([state.categoryId, state.nameColumnKey, "", state.countColumnKey, state.selectedColumnKeys])}}});
            dispatch(stockApi.util.invalidateTags(["Stock"]));
            toast.success(t("Products from the file were imported."));
        } catch (error) {toast.error(getApiErrorMessage(error, t("Products from the file could not be imported.")));}
    };

    return <MainDiv>
        <PageHeader><PageTitleGroup><PageTitle>{t("Product review")}</PageTitle><PageSubtitle>{"Проверьте названия и характеристики перед сохранением карточек. Цены можно внести позже; до заполнения закупочной цены, себестоимости, надбавки и конечной цены новые карточки неактивны для заказов."}</PageSubtitle></PageTitleGroup><CoreButton muiType="secondary" leftIcon={<ArrowBackOutlinedIcon/>} text={t("Back")} onClick={backToSelection}/></PageHeader>
        <CatalogGenerationTabs/>
        <Steps><Step>1. {t("File")}</Step><Step>2. {t("Column mapping")}</Step><Step $active>3. {t("Product review")}</Step></Steps>
        <Workspace>
            {persistenceWarning && <Alert severity="warning">Не удалось сохранить черновик в браузере. Не обновляйте страницу до сохранения карточек.</Alert>}
            {state.analysis?.isEpassDocument && <Alert severity="info">Новые карточки будут созданы с остатком 0. Остатки существующих товаров сохранятся. «Количество товара» из ePass — характеристика упаковки; приход оформляется отдельно в разделе склада.</Alert>}
            <Alert severity="info">{result ? "Обработка завершена. Откройте карточки товаров, чтобы проверить сохранённые данные." : "Дважды нажмите на ячейку, чтобы изменить значение. Снимите флажок у строки, которую нужно исключить. Товары сопоставляются по GTIN; значения из файла обновляются, другие дополнительные поля карточки сохраняются. Пустые значения не стирают ранее заполненные поля."}</Alert>
            <Alert severity={!state.analysis?.isEpassDocument && updateStock ? "warning" : "info"}>Цены вносятся после импорта в карточках товаров. Цены существующих товаров сохраняются. {state.analysis?.isEpassDocument ? "Для новых карточек остаток равен 0." : "По умолчанию остатки существующих товаров сохраняются; для новых карточек используются количества таблицы."} Поступление товара оформляйте через <a href="#/warehouseReceipts">приёмку на склад</a>.</Alert>
            {!state.analysis?.isEpassDocument && <div><FormControlLabel control={<Checkbox disabled={result !== null || productImport.isLoading} checked={updateStock} onChange={event => setUpdateStock(event.target.checked)}/>} label="Заменить остатки существующих товаров значениями таблицы"/></div>}
            <Chip label={`К сохранению: ${rows.length - excluded.length} · Исключено: ${excluded.length}`}/>
            <TopBar><div><strong>{state.preview.fileName}</strong><Summary><Chip size="small" color="primary" variant="outlined" label={t("{count} products", {count: rows.length})}/><Chip size="small" variant="outlined" label={categoryName ?? `#${state.categoryId}`}/><Chip size="small" variant="outlined" label={t("{count} fields", {count: state.preview.selectedColumns.length + customFields.length})}/></Summary></div>{result && <Alert severity="success">{t("Created: {created}; updated: {updated}; skipped: {skipped}", {created: result.created, updated: result.updated, skipped: result.skipped})}</Alert>}</TopBar>
            {state.preview.warnings.length > 0 && <Alert severity="warning">{state.preview.warnings.slice(0, 5).join(" ")}</Alert>}
            {!state.analysis?.isEpassDocument && <Accordion disableGutters><AccordionSummary expandIcon={<ExpandMoreOutlinedIcon/>}><strong>{t("Bulk changes")}</strong></AccordionSummary><AccordionDetails><BulkGrid><TextField size="small" type="number" disabled={result !== null || productImport.isLoading} label="Количество выбранных товаров" value={bulkCount} inputProps={{min: 0, step: "0.01"}} onChange={(event) => setBulkCount(event.target.value)}/><CoreButton muiType="secondary" text={t("Apply")} disabled={result !== null || productImport.isLoading} onClick={applyBulkCount}/></BulkGrid></AccordionDetails></Accordion>}
            <Accordion defaultExpanded disableGutters><AccordionSummary expandIcon={<ExpandMoreOutlinedIcon/>}><strong>Свои колонки для карточек ({customFields.length})</strong></AccordionSummary><AccordionDetails><Alert severity="info" sx={{mb: 2}}>Добавьте любую колонку к уже разобранной таблице: например, артикул, бренд или место хранения. Значение по умолчанию можно изменить отдельно в каждой строке. Колонки сохранятся как дополнительные поля карточек.</Alert><AddFieldGrid><TextField size="small" disabled={result !== null || productImport.isLoading} label={t("Field name")} value={newFieldName} inputProps={{maxLength: 100}} onChange={(event) => setNewFieldName(event.target.value)}/><TextField size="small" disabled={result !== null || productImport.isLoading} label={t("Default value (optional)")} value={newFieldDefault} inputProps={{maxLength: 250}} onChange={(event) => setNewFieldDefault(event.target.value)}/><CoreButton muiType="secondary" leftIcon={<AddOutlinedIcon/>} text="Добавить колонку" disabled={result !== null || productImport.isLoading} onClick={addCustomField}/></AddFieldGrid>{customFields.length > 0 && <FieldChips>{customFields.map((field) => <Chip key={field.id} size="small" label={`${field.name}${field.defaultValue ? `: ${field.defaultValue}` : ""}`} onDelete={result || productImport.isLoading ? undefined : () => removeCustomField(field)}/>)}</FieldChips>}</AccordionDetails></Accordion>
            <StyledDataGrid apiRef={apiRef} checkboxSelection isRowSelectable={() => result === null && !productImport.isLoading} rowSelectionModel={rows.filter(row => !excluded.includes(row.id)).map(row => row.id)} onRowSelectionModelChange={ids => {if (result || productImport.isLoading) return; setExcluded(rows.filter(row => !ids.includes(row.id)).map(row => row.id));}} autoHeight rows={rows} columns={columns} slots={{toolbar: GridToolbar}} slotProps={{toolbar: {showQuickFilter: true}}} onCellEditStart={(params) => {editingCellRef.current = {id: params.id, field: params.field};}} onCellEditStop={(params) => {if (params.reason !== GridCellEditStopReasons.escapeKeyDown) {const nextRow = apiRef.current.getRowWithUpdatedValues(params.id, params.field) as EditableProductRow; updateRow(nextRow);} editingCellRef.current = null;}} processRowUpdate={(nextRow) => updateRow(nextRow as EditableProductRow)} onProcessRowUpdateError={() => toast.error(t("The table value could not be changed."))} pageSizeOptions={[25, 50, 100]} initialState={{pagination: {paginationModel: {pageSize: 25, page: 0}}}} disableRowSelectionOnClick/>
            {productImport.isLoading && <LinearProgress/>}<Footer><CoreButton muiType="secondary" text={t("Back")} onClick={backToSelection}/><CoreButton muiType="success" disabled={productImport.isLoading || rows.length === excluded.length || result !== null} text={productImport.isLoading ? t("Importing products...") : `Сохранить карточки (${rows.length - excluded.length})`} onClick={() => void runImport()}/></Footer>
            {result && <Footer><CoreButton muiType="secondary" text="Открыть карточки товаров" onClick={() => navigate("/productsManagement", {replace: true})}/><CoreButton text="Принять товары на склад" onClick={() => navigate("/warehouseReceipts", {replace: true})}/><CoreButton muiType="secondary" text="Загрузить файл для прихода" onClick={() => navigate("/invoices", {replace: true})}/></Footer>}
        </Workspace>
    </MainDiv>;
};

export default ProductFileReviewPage;
